from src.string_tools import normalize_whitespace


def test_normalize_newlines():
    assert normalize_whitespace("hello\nworld") == "hello world"
    assert normalize_whitespace("line1\r\nline2") == "line1 line2"


def test_normalize_tabs():
    assert normalize_whitespace("hello\tworld") == "hello world"
    assert normalize_whitespace("col1\t\tcol2") == "col1 col2"


def test_normalize_multiple_spaces():
    assert normalize_whitespace("hello   world") == "hello world"
    assert normalize_whitespace("a   b    c") == "a b c"


def test_normalize_mixed_whitespace():
    assert normalize_whitespace("hello \t \n world") == "hello world"


def test_strip_leading_trailing():
    assert normalize_whitespace("  hello world  ") == "hello world"
    assert normalize_whitespace("\n\thello\n") == "hello"

